def get_frequencies(input_iterable):
    freq = {}
    for item in input_iterable:
        freq[item] = freq.get(item, 0) + 1
    return freq

def get_letter_frequencies(word):
    return get_frequencies(word)

def calculate_similarity_score(freq_dict1, freq_dict2):
    diff = 0
    for k in set(freq_dict1) | set(freq_dict2):
        diff += abs(freq_dict1.get(k, 0) - freq_dict2.get(k, 0))
    total = sum(freq_dict1.values()) + sum(freq_dict2.values())
    if total == 0:
        return 1.0
    return round(1 - (diff / total), 2)

def get_most_frequent_words(freq_dict1, freq_dict2):
    combined = {}
    for d in (freq_dict1, freq_dict2):
        for k, v in d.items():
            combined[k] = combined.get(k, 0) + v
    if not combined:
        return []
    max_freq = max(combined.values())
    return sorted([k for k in combined if combined[k] == max_freq])

