problems.solution:
import string
import math

### DO NOT MODIFY — provided by the pset.
def load_file(filename):
    inFile = open(filename, 'r')
    line = inFile.read().strip()
    for char in string.punctuation:
        line = line.replace(char, "")
    inFile.close()
    return line.lower()

def text_to_list(input_text):
    return input_text.split()

def get_frequencies(input_iterable):
    freq = {}
    for item in input_iterable:
        freq[item] = freq.get(item, 0) + 1
    return freq

def get_tf(file_path):
    words = text_to_list(load_file(file_path))
    freq = get_frequencies(words)
    total = len(words)
    return {word: count / total for word, count in freq.items()}

def get_idf(file_paths):
    doc_count = len(file_paths)
    word_docs = {}
    for p in file_paths:
        for word in set(text_to_list(load_file(p))):
            word_docs[word] = word_docs.get(word, 0) + 1
    return {word: math.log10(doc_count / count) for word, count in word_docs.items()}

def get_tfidf(tf_file_path, idf_file_paths):
    tf = get_tf(tf_file_path)
    idf = get_idf(idf_file_paths)
    result = [(word, tf[word] * idf[word]) for word in tf]
    result.sort(key=lambda pair: (pair[1], pair[0]))
    return result
